require 'json';require 'fileutils';require 'open3';root=File.expand_path('..',__dir__);jdk=File.expand_path('../.toolchains/jdk-26.0.2.1.jdk/Contents/Home',root);source=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/room/RoomCodePolicy.java'));stdout,stderr,status=Open3.capture3({'JAVA_HOME'=>jdk,'PATH'=>"#{jdk}/bin:#{ENV['PATH']}"},'./mvnw','-q','-pl','server/GameCommon','-am','-Dtest=RoomCodePolicyTest','-Dsurefire.failIfNoSpecifiedTests=false','test',chdir:root);checks={secure_random:source.include?('SecureRandom'),fixed_length:source.include?('LENGTH=8'),unambiguous_alphabet:!source.match(/ALPHABET="[^"]*[01ILO]/),collision_budget:source.include?('attempt<32'),reuse_quarantine:source.include?('reuseQuarantine'),input_normalization:source.include?('normalize(String input)'),tests_passed:status.success?};result={task:'LINK01',passed:checks.values.all?,checks:checks,testStdout:stdout.strip,testStderr:stderr.strip};out=File.join(root,'work/audit/room-code-policy.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");puts JSON.generate(result);exit(result[:passed] ? 0 : 1)
